@Test
public void testLookup() throws IOException {
    final String resourceDir = "src/test/resources/cmap";
    File inDir = new File(resourceDir);
    CMapParser parser = new CMapParser();
    CMap cMap = parser.parse(new File(inDir, "CMapTest"));
    // char mappings
    byte[] bytes1 = { 0, 1 };
    Assert.assertEquals("bytes 00 01 from bfrange <0001> <0005> <0041>", "A", cMap.toUnicode(bytes1));
    byte[] bytes2 = { 1, 00 };
    String str2 = "0";
    Assert.assertEquals("bytes 01 00 from bfrange <0100> <0109> <0030>", str2, cMap.toUnicode(bytes2));
    byte[] bytes3 = { 1, 32 };
    Assert.assertEquals("bytes 01 00 from bfrange <0100> <0109> <0030>", "P", cMap.toUnicode(bytes3));
    byte[] bytes4 = { 1, 33 };
    Assert.assertEquals("bytes 01 00 from bfrange <0100> <0109> <0030>", "R", cMap.toUnicode(bytes4));
    byte[] bytes5 = { 0, 10 };
    String str5 = "*";
    Assert.assertEquals("bytes 00 0A from bfchar <000A> <002A>", str5, cMap.toUnicode(bytes5));
    byte[] bytes6 = { 1, 10 };
    String str6 = "+";
    Assert.assertEquals("bytes 01 0A from bfchar <010A> <002B>", str6, cMap.toUnicode(bytes6));
    // CID mappings
    byte[] cid1 = new byte[] { 0, 65 };
    Assert.assertEquals("CID 65 from cidrange <0000> <00ff> 0 ", 65, cMap.toCID(cid1));
    byte[] cid2 = new byte[] { 1, 24 };
    int strCID2 = 0x0118;
    Assert.assertEquals("CID 280 from cidrange <0100> <01ff> 256", strCID2, cMap.toCID(cid2));
    byte[] cid3 = new byte[] { 2, 8 };
    int strCID3 = 0x0208;
    Assert.assertEquals("CID 520 from cidchar <0208> 520", strCID3, cMap.toCID(cid3));
    byte[] cid4 = new byte[] { 1, 0x2c };
    int strCID4 = 0x12C;
    Assert.assertEquals("CID 300 from cidrange <0300> <0300> 300", strCID4, cMap.toCID(cid4));
}

