/**
 * PDFBOX-4421: Read a file encrypted with AES128 but not with PDFBox, and with missing /Length
 * entry. Test to be changed so it's done locally with small file.
 *
 * @throws IOException
 */
@Test
public void testReadPubkeyEncryptedAES128() throws IOException {
    try (InputStream is = TestPublicKeyEncryption.class.getResourceAsStream("AESkeylength128.pdf");
        PDDocument doc = Loader.loadPDF(is, "w!z%C*F-JaNdRgUk", TestPublicKeyEncryption.class.getResourceAsStream("PDFBOX-4421-keystore.pfx"), "testnutzer")) {
        Assert.assertEquals("PublicKeySecurityHandler", doc.getEncryption().getSecurityHandler().getClass().getSimpleName());
        Assert.assertEquals(128, doc.getEncryption().getSecurityHandler().getKeyLength());
        PDFTextStripper stripper = new PDFTextStripper();
        Assert.assertEquals("Key length: 128", stripper.getText(doc).trim());
    }
}

