    field.setValue(field.getFullyQualifiedName() + "\n" + TEST_VALUE);
    field = acroForm.getField("pdfbox.portrait.multi.rotation90");
    field.setValue(field.getFullyQualifiedName() + "\n" + TEST_VALUE);
    field = acroForm.getField("pdfbox.portrait.multi.rotation180");
